const {deviceState,syncDevice}=require('../../utils/page')
const {askCoach,isAuthError}=require('../../utils/api')
const {coachHelpPolicy}=require('../../utils/coach')
const {TAVERN_PRESETS,tavernPreset}=require('./tavernPresets')
const owner=()=>String(wx.getStorageSync('stemistUser')?.id||'guest'),epoch=()=>Number(wx.getStorageSync('stemistPrivacyEpoch'))||0
Page({
 onShareAppMessage(){return require('../../utils/share').onShareAppMessage.call(this)},
 data:deviceState({personas:TAVERN_PRESETS,selected:TAVERN_PRESETS[0],persona:'keeper',starters:TAVERN_PRESETS[0].starters,greeting:TAVERN_PRESETS[0].greeting,placeholder:TAVERN_PRESETS[0].placeholder,selectorOpen:true,presetChosen:false,message:'',turns:[],answer:'',loading:false,error:'',warning:'',canRetry:false,authRequired:false,status:'',examBlocked:false}),
 onLoad(options){this.__owner=owner();this.__epoch=epoch();this.__disposed=false;this.__states={};this.__attemptId='';let blocked=false;const key=String(options?.entry||''),entry=wx.getStorageSync('stemistCoachEntry'),age=Date.now()-Number(entry?.at);if(key&&entry?.key===key&&entry.owner===this.__owner&&entry.epoch===this.__epoch&&age>=0&&age<120000){const context=entry.context||{},attempt=context.attempt||{};this.__attemptId=String(context.attemptId||context.paperAttemptId||attempt.id||attempt.attemptId||'');blocked=coachHelpPolicy(context).solutionDisabled}const initial=this.initialPersona();this.loadPersona(initial.persona,{chosen:initial.chosen,open:!initial.chosen});if(blocked)this.setData({examBlocked:true,error:'计时考试进行中，休闲酒馆暂不可用；请先完成或退出本次考试。'})},
 onShow(){syncDevice(this);if(this.__authResumeRequested&&wx.getStorageSync('stemistSessionToken')&&owner()===this.__owner&&epoch()===this.__epoch){this.__authResumeRequested=false;this.loadPersona(this.data.persona,{chosen:true,open:false});return}if(!this.current())this.setData({message:'',turns:[],answer:'',loading:false,canRetry:false,authRequired:false,status:'',error:'账号状态已变化，请返回后重新进入酒馆。'})},onResize(){syncDevice(this)},
 onUnload(){if(this.current())this.save(false);this.__disposed=true},current(){return !this.__disposed&&this.__owner===owner()&&this.__epoch===epoch()},
 key(persona=this.data.persona){return`stemistTavern:${this.__owner}:${this.__epoch}:${persona}`},
 selectionKey(){return`stemistTavern:${this.__owner}:${this.__epoch}:selected`},
 read(persona){let state=this.__states[persona];if(!state)try{state=wx.getStorageSync(this.key(persona))}catch{}return state&&state.owner===this.__owner&&state.epoch===this.__epoch&&state.persona===persona?state:{draft:'',turns:[]}},
 initialPersona(){let selected='';try{selected=String(wx.getStorageSync(this.selectionKey())||'')}catch{}if(tavernPreset(selected))return{persona:selected,chosen:true};for(const preset of TAVERN_PRESETS){const state=this.read(preset.id);if(String(state.draft||'')||Array.isArray(state.turns)&&state.turns.length)return{persona:preset.id,chosen:true}}return{persona:'keeper',chosen:false}},
 save(warn=true){if(!this.current())return false;const state={owner:this.__owner,epoch:this.__epoch,persona:this.data.persona,draft:this.data.message,turns:this.data.turns.slice(-12)};this.__states[this.data.persona]=state;try{wx.setStorageSync(this.key(),state);if(warn&&this.data.warning)this.setData({warning:''});return true}catch{if(warn)this.setData({warning:'当前对话未能保存在本机；本页内内容仍保留，请暂时不要退出。'});return false}},
 rememberPersona(persona){this.__selectedPersona=persona;try{wx.setStorageSync(this.selectionKey(),persona);return true}catch{this.setData({warning:'当前预设未能保存在本机；本页内选择仍然有效。'});return false}},
 loadPersona(persona,{chosen=this.data.presetChosen,open=this.data.selectorOpen}={}){const selected=tavernPreset(persona)||TAVERN_PRESETS[0],state=this.read(selected.id);this.setData({selected,persona:selected.id,starters:selected.starters,greeting:selected.greeting,placeholder:selected.placeholder,selectorOpen:open,presetChosen:chosen,message:String(state.draft||''),turns:Array.isArray(state.turns)?state.turns.slice(-12):[],answer:'',error:this.data.examBlocked?this.data.error:'',warning:'',canRetry:false,authRequired:false,status:''})},
 openSelector(){if(this.current()&&!this.data.loading&&!this.data.examBlocked)this.setData({selectorOpen:true})},
 choosePersona(event){if(!this.current()||this.data.loading||this.data.examBlocked)return;const persona=String(event.currentTarget?.dataset?.persona||'');if(!tavernPreset(persona))return;if(this.data.presetChosen)this.save();this.loadPersona(persona,{chosen:true,open:false});this.rememberPersona(persona)},
 onMessage(event){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.presetChosen)return;this.setData({message:String(event.detail?.value||''),error:'',authRequired:false});this.save()},
 useStarter(event){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.presetChosen)return;const message=String(event.currentTarget?.dataset?.text||'');if(!this.data.starters.includes(message))return;this.setData({message,error:'',authRequired:false});this.save()},
 async submit(){const message=this.data.message.trim();if(!message||this.data.loading||!this.current()||this.data.examBlocked||!this.data.presetChosen)return;if(message.length>1200)return this.setData({error:'一次最多输入 1200 个字。'});this.setData({loading:true,error:'',answer:'',canRetry:false,authRequired:false,status:'AI 正在回应…'});try{const result=await askCoach({message,feature:'tavern',persona:this.data.persona,attemptId:this.__attemptId,context:{product:'STEM Studio',skill:'tavern',stage:'practice',source:'stemist-miniprogram'},imageDataUrls:[],history:this.data.turns.slice(-10)});if(!this.current())return;const answer=String(result?.answer||result?.message||'').trim(),completed=result?.mode==='ai'&&result?.providerStatus==='connected'&&Boolean(answer);if(!completed)throw new Error(result?.failureMessage||'AI 本次没有完成回应，文字已保留，请重试。');const turns=[...this.data.turns,{role:'user',content:message},{role:'assistant',content:answer}].slice(-12);this.setData({message:'',turns,answer,status:'AI 已回应',canRetry:false});this.save()}catch(error){const auth=isAuthError(error);if(auth&&epoch()===this.__epoch&&owner()==='guest')this.setData({message:'',turns:[],answer:'',error:'登录已过期，请登录后继续。',canRetry:false,authRequired:true,status:'对话未完成',loading:false});else if(this.current()){this.setData({answer:'',error:error.message||'AI 暂时不可用，文字已保留。',canRetry:!auth,authRequired:auth,status:'对话未完成'});this.save()}}finally{if(this.current()||this.data.authRequired)this.setData({loading:false})}},
 retry(){if(!this.data.loading)this.submit()},openAccount(){this.__authResumeRequested=true;wx.navigateTo({url:'/pages/account/auth'})},
 clear(){if(this.data.loading||!this.current()||!this.data.presetChosen)return;const key=this.key(),state={owner:this.__owner,epoch:this.__epoch,persona:this.data.persona,draft:'',turns:[]};this.__states[this.data.persona]=state;let persisted=true;try{wx.removeStorageSync(key)}catch{try{wx.setStorageSync(key,state)}catch{persisted=false}}this.setData({message:'',turns:[],answer:'',error:'',warning:persisted?'':'本机记录未能清除；请释放空间或稍后重试清空。',canRetry:false,authRequired:false,status:persisted?'已清空当前角色对话':'本页内容已隐藏'})},
})
